pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: actor address
    function testFuzz_property(address actor) public {
        // keep actor non-zero to be meaningful
        vm.assume(actor != address(0));

        // Ensure actor starts with zero balance in contract storage (admissible domain)
        // We cannot directly set tokenBalance, but the contract's initial mapping default is 0.
        // Guarantee actor has no ETH so only tokenBalance matters; not strictly necessary but safe.
        vm.deal(actor, 0);

        // Pretend the call comes from actor
        vm.prank(actor);
        // Call airDrop on c. The reference increases tokenBalance[actor] by 20; mutant may not.
        c.airDrop();

        // Single assertion: after airDrop, tokenBalance(actor) == 20
        // This is true for the reference for any actor with initial zero balance and supported token
