pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: actor that will call airDrop and an unrelated address k to observe balances
    function testFuzz_property(address actor, address k) public {
        vm.assume(actor != address(0));
        vm.assume(k != address(0));
        vm.assume(actor != address(c));
        vm.assume(k != address(c));

        // ensure actor has zero tokenBalance initially (as in contract default)
        // We also ensure actor behaves as Bank by deploying a tiny Bank-like helper that returns the expected bytes32
        BankLike bank = new BankLike();

        // prepare actor to be seen as a contract supporting the token: we need c to call Bank(msg.sender).supportsToken()
        // So we must make the call come from the BankLike contract; the fuzzer supplies actor, so we impersonate bank as actor via prank
        // but supportsToken is read from msg.sender inside modifier, so msg.sender must be the BankLike address

        // First call: perform airDrop from bank (which supports token) while ensuring bank has no token balance yet
        vm.prank(address(bank));
        c.airDrop();

        uint256 before = c.tokenBalance(address(bank));

        // Second call: attempt another airDrop from same sender
        bool ok;
        vm.prank(address(bank));
        try c.airDrop() {
            ok = true;
        } catch {
            ok = false;
        }

        uint256 after = c.tokenBalance(address(bank));

        // General property: Reference releases lock so subsequent airDrop can proceed (ok == true) and balance doesn't decrease.
        // Buggy mutant that doesn't release lock may make the second call fail (ok == false) and leave balance unchanged while reference would have increased it.
        // We assert the universal property: after >= before (non-decreasing) — reference satisfies for all inputs; mutant can break it for some inputs
        assertTrue(after >= before);
    }
}

