pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz parameters: caller (who will receive tokens) and helper (external contract that msg.sender will be)
    // We deploy a small Forwarder that forwards calls and makes msg.sender appear as the Bank external contract
    function testFuzz_property(address caller, address helperSeed) public {
        // Keep addresses in admissible domain: non-zero
        vm.assume(caller != address(0));
        // helperSeed used only to vary creation salt so fuzzer can explore many helper addresses

        // Deploy an attacker-like helper that simply forwards calls to C and reports support for the token
        // We deploy a fresh Forwarder with deterministic salt derived from helperSeed to give fuzzer power
        Forwarder f = new Forwarder{salt: bytes32(uint256(uint160(helperSeed)))}(address(c));

        // Ensure caller has ETH to cover gas (not strictly necessary but safe)
        vm.deal(caller, 1 ether);

        // The protocol expects Bank(msg.sender).supportsToken() to be called; our Forwarder will respond correctly.
        // We need to have the actual airDrop executed with msg.sender == address(f), and msg.sender's tokenBalance to be 0 initially.
        // To make the call originate from caller but with msg.sender == f, we have the Forwarder call c.airDrop on behalf of caller.

        // First, ensure tokenBalance[caller] == 0 initially
        // (can't assume storage elsewhere mutated it) but if not zero the property still should hold; keep wide.

        // Arrange: caller instructs Forwarder to call c.airDrop() using a low-level call from the Forwarder, with the Forwarder set up to call as if supporting the token.
        // Perform first airDrop: expected to succeed on both reference and mutant (first call acquires lock)
        vm.prank(caller);
        f.forwardAirDrop();

        uint256 afterFirst = c.tokenBalance(caller);

        // Perform second airDrop in the same fashion: on the correct contract this should increase again (or at least not decrease);
        // on the mutant that never releases the lock the second call will revert or have no effect.
        vm.prank(caller);
        bool ok;
        try f.forwardAirDrop() {
            ok = true;
        } catch {
            ok = false;
        }

        uint256 afterSecond = c.tokenBalance(caller);

        // General fact: on the correct contract, afterSecond >= afterFirst (tokenBalance is non-decreasing across sequential airDrops by the same caller routed through a helper that supports the token).
        // This single assert reads c's public getter and distinguishes the mutant which may leave the lock set and cause the second call to fail, making afterSecond < afterFirst or equal without increase.
        assertTrue(afterSecond >= afterFirst);
    }
}

// Minimal helper that acts as the external Bank contract and forwards an airDrop call to C.
contract Forwarder {
    address public target;
    constructor(address _target) {
        target = _target;
    }

    // Report that we support the token (matches keccak256("Nu Token"))
    function supportsToken() external pure returns (bytes32) {
        return keccak256(abi.encodePacked("Nu Token"));
    }

    // Called by the fuzzed EOA (caller) to instruct this Forwarder to call C.airDrop()
    function forwardAirDrop() external {
        // Forward a plain call to target.airDrop(); msg.sender for C will be address(this), so supportsToken() will be called on this contract.
        (bool success, ) = target.call(abi.encodeWithSignature("airDrop()"));
        require(success);
    }
}

