pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzzed parameters: two distinct addresses to act as two callers.
    // We must deploy a helper that returns the correct supportsToken value and will be used as msg.sender
    // for the supportsToken check by making the callers call through the helper (helper will forward calls
    // so that in the callee's context msg.sender == helper). To achieve that we make the helper perform
    // a low-level call to c.airDrop while setting tx.origin/prank as the original caller. But simpler: helper
    // is the callee for supportsToken (c expects msg.sender to be a Bank contract), so callers will set
    // msg.sender==helper by performing a call to helper which in turn calls c.airDrop; helper's call makes
    // c see msg.sender==helper for supportsToken. We fuzz the two callers' addresses so the fuzzer can find
    // a pair that distinguishes the mutant.
    function testFuzz_property(address addrA, address addrB) public {
        // Keep addresses non-zero and distinct and avoid collisions with this contract
        vm.assume(addrA != address(0));
        vm.assume(addrB != address(0));
        vm.assume(addrA != addrB);
        vm.assume(addrA != address(this));
        vm.assume(addrB != address(this));

        // Give the callers some ETH to pay gas
        vm.deal(addrA, 1 ether);
        vm.deal(addrB, 1 ether);

        // Deploy a benign helper that reports support for the token and can forward calls to c.airDrop
        HelperBank helper = new HelperBank(c);

        // 1) addrA triggers an airDrop via the helper so c sees msg.sender == address(helper)
        vm.prank(addrA);
        helper.callAirDrop(); // should succeed on reference

        // After that, on the correct contract the reentrancy lock is released. Therefore a fresh caller
        // addrB doing the same sequence (call through helper) should also receive 20 tokens.
        vm.prank(addrB);
        helper.callAirDrop();

        // Exactly one assertion: on the reference implementation, addrB's tokenBalance must be 20
        // (the reference releases the lock after the first call allowing the second to succeed). The mutant
        // that never resets _locked can prevent the second call and leave tokenBalance(addrB) == 0,
        // which the fuzzer can find.
        assertTrue(c.tokenBalance(addrB) == 20);
    }
}

// Helper contract that acts as the Bank (supportsToken) and forwards calls to C.airDrop so that
// inside C the msg.sender for supportsToken is this helper contract.
contract HelperBank {
    C public target;
    constructor(C _c) { target = _c; }
    // supportsToken must match keccak256("Nu Token") as in the original
    function supportsToken() external pure returns (bytes32) {
        return(keccak256(abi.encodePacked("Nu Token")));
    }
    // Called by an EOA (fuzzed addr); this function will call target.airDrop(), making target see
    // msg.sender == address(this) which triggers supportsToken.
    function callAirDrop() external {
        // forward the call to target.airDrop()
        target.airDrop();
    }
}

