pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz two addresses: callerA and callerB. They must be distinct and non-zero.
    function testFuzz_property(address callerA, address callerB) public {
        // keep domain meaningful
        vm.assume(callerA != address(0));
        vm.assume(callerB != address(0));
        vm.assume(callerA != callerB);

        // Deploy a helper bank that reports support for the token; C's supportsToken expects msg.sender to be a Bank
        BankHelper helper = new BankHelper();

        // Fund the callers so they can make calls (not strictly necessary but safe)
        vm.deal(callerA, 1 ether);
        vm.deal(callerB, 1 ether);

        // First, have callerA perform airDrop while msg.sender for supportsToken is the helper.
        // The supportsToken modifier in C uses Bank(msg.sender).supportsToken() so we must make the call
        // such that msg.sender inside supportsToken is helper. Achieve by having callerA call helper which then calls c.airDrop.

        // Ensure initial balances are zero (admissible domain)
        // Make the routed call: helper will call c.airDrop() using tx.origin-style imitation: helper.callAirdropFrom(callerA)
        vm.startPrank(callerA);
        helper.callAirdrop(address(c));
        vm.stopPrank();

        // After this, reference contract releases lock so B's subsequent airDrop should succeed and set balance 20.
        // We now have callerB have helper route an identical second airDrop.
        vm.startPrank(callerB);
        // call inside try/catch to observe whether call succeeded on this contract version
        bool ok;
        try helper.callAirdrop(address(c)) {
            ok = true;
        } catch {
            ok = false;
        }
        vm.stopPrank();

        // The universal property to assert: on the reference, B's balance equals 20 (i.e., its airDrop succeeded).
        // We read c.tokenBalance(callerB) which is a public getter. This is the single assertion.
        assertTrue(c.tokenBalance(callerB) == 20);
    }
}

// Minimal helper that acts as a Bank and forwards calls to C.airDrop so that inside supportsToken the msg.sender is this helper.
contract BankHelper {
    function supportsToken() external pure returns (bytes32) {
        return keccak256(abi.encodePacked("Nu Token"));
    }

    // Called by an EOA (the fuzzed caller) via vm.prank(caller); helper.callAirdrop(c)
    // This makes msg.sender==helper when C.supportsToken() is invoked.
    function callAirdrop(address c) external {
        C(c).airDrop();
    }
}

