pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz two addresses: callerA and callerB. They must be distinct EOAs that will be used as msg.senders.
    function testFuzz_property(address callerA, address callerB) public {
        // keep them distinct and non-zero
        vm.assume(callerA != address(0));
        vm.assume(callerB != address(0));
        vm.assume(callerA != callerB);

        // Both callers must be treated as contracts by the supportsToken modifier, which calls Bank(msg.sender).supportsToken().
        // The fuzzed addresses are EOAs (no code). To satisfy supportsToken, we must route the external call such that msg.sender
        // for the supportsToken invocation is a contract that returns the expected hash. The supportsToken modifier does:
        // require(keccak256(abi.encodePacked("Nu Token")) == Bank(msg.sender).supportsToken());
        // So we need to make msg.sender be a contract that returns keccak256("Nu Token"). We'll deploy a tiny helper and then
        // use vm.prank(helperAddress) to make the C contract see the helper as msg.sender during the airDrop call.

        // Deploy helper that reports support
        HelperSupport hs = new HelperSupport();

        // Ensure both callers have some ETH for transactions (not strictly needed but safe)
        vm.deal(callerA, 1 ether);
        vm.deal(callerB, 1 ether);

        // First, have callerA perform airDrop but make the C contract observe msg.sender == address(hs) for supportsToken check.
        vm.prank(callerA);
        // Inside C.airDrop the supportsToken modifier does Bank(msg.sender).supportsToken(), where msg.sender must be a contract.
        // However msg.sender in that external call is the origination of the transaction (callerA). To make Bank(msg.sender) point to
        // our helper, we instead call C.airDrop while setting tx.origin to callerA and the msg.sender seen by C to be hs. The simplest
        // way is to have callerA call hs which forwards the call to c with hs as msg.sender. We instead have hs.forwardAirDropPrankedBy
        // use delegatecall-like behavior isn't allowed. Simpler: have hs.callAirDropFrom(address caller) that performs c.airDrop() but
        // with hs as msg.sender — so we need to have callerA call hs, and hs will in turn call c.airDrop(), so c sees hs as msg.sender
        // (the helper will call c.airDrop() directly). Thus we vm.prank(callerA) to have the external call originate from callerA to hs,
        // and hs then calls c.airDrop() so C sees hs as msg.sender for the supportsToken check.
        vm.prank(callerA);
        hs.callAirDrop(address(c));

        // After the call, on the correct contract tokenBalance(callerA) == 20. We now attempt to have callerB also acquire tokens.
        // Do the same: have callerB call hs which forwards the call to c so c sees hs as msg.sender for supportsToken.
        vm.prank(callerB);
        bool ok;
        try hs.callAirDropReturn(address(c)) {
            ok = true;
        } catch {
            ok = false;
        }

        // On the correct contract, after A's airDrop completes, the lock is released so B's subsequent airDrop (routed through the same helper)
        // should succeed and set tokenBalance(callerB) == 20. We assert that tokenBalance(callerB) == 20. This is the single assertion.
        // The buggy mutant that never releases the lock can leave the contract permanently locked after the first call and make the second
        // call fail, causing tokenBalance(callerB) != 20 for some inputs; the fuzzer can find such input pair.
        assertTrue(c.tokenBalance(callerB) == 20);
    }
}

// Minimal helper contract that reports support and forwards calls to C so that C sees the helper as msg.sender
contract HelperSupport {
    function supportsToken() external pure returns (bytes32) {
        return keccak256(abi.encodePacked("Nu Token"));
    }

    // call c.airDrop() so that within C the msg.sender is this helper contract
    function callAirDrop(address caddr) external {
        C(caddr).airDrop();
    }

    // wrapper that returns so try/catch can detect revert
    function callAirDropReturn(address caddr) external returns (bool) {
        C(caddr).airDrop();
        return true;
    }
}

