    C c;
    function setUp() public { c = new C(); }

    // fuzz the caller address; for any caller with initial zero balance, after airDrop the reference
    // increases their tokenBalance by exactly 20 — the mutant that adds 10 will produce a different final balance
    function testFuzz_property(address caller) public {
        // avoid the zero address because external call expectations (Bank expects msg.sender to be a contract when checking supportsToken())
        vm.assume(caller != address(0));

        // ensure caller has zero token balance initially
        // tokenBalance is public, so read via getter
        uint256 before = c.tokenBalance(caller);
