        // meaning msg.sender must be a contract implementing supportsToken. The fuzzer provides an address which
        // is an EOA with no code; to satisfy the modifier we must call airDrop from a contract that implements supportsToken().
        // Deploy a tiny helper BankLike and have it call into c.airDrop() on behalf of the fuzzed caller identity.

        HelperCaller helper = new HelperCaller(address(c));

        // Use vm.prank to make the helper act as if tx.origin is the fuzzed caller? The modifier uses msg.sender inside c,
        // and since helper will perform the external call into c, msg.sender inside c will be helper. The supportsToken() call
        // will be to Bank(msg.sender) i.e., helper.supportsToken(), so helper must implement supportsToken to return the correct bytes32.
